<script lang="ts">
  import { page } from '$app/state';
  import { goto } from '$app/navigation';
  import Icon from '$lib/components/Icon.svelte';
  import StatusPill from '$lib/components/StatusPill.svelte';
  import { catalogueCategories } from '$lib/stores/catalogue';
  import { creatorProfile, creatorProducts, loadCreatorData, removeCreatorProduct, setProductStatus, storefront, updateCreatorProduct } from '$lib/stores/creator';
  import { showToast } from '$lib/stores/marketplace';
  import { apiRequest } from '$lib/api';
  import { getSupabaseBrowserClient } from '$lib/supabase/client';
  import { parseShowcaseVideoUrl } from '$lib/showcase-video';

  let tab='Overview';
  $: product=$creatorProducts.find((item)=>item.slug===page.params.slug);
  let seededSlug='';
  let title='';let category='';let summary='';let description='';let price=0;let extendedPrice=0;
  let compatibility='GameGuru MAX';let maxVersion='Any MAX build';let sourceFiles=false;let dependencies='None';let performance:'Lightweight'|'Mid-range'|'High detail'='Mid-range';let licence='Standard commercial licence';
  let tagsText='';let featuresText='';let contentsText='';let formatsText='';let showcaseVideoUrl='';
  let showcaseVideo:ReturnType<typeof parseShowcaseVideoUrl>=null;let showcaseVideoError='';
  let versionNumber='';let releaseNotes='';let packageFile:File|undefined;let documentationFile:File|undefined;let versionBusy=false;

  $: if(product&&product.slug!==seededSlug){
    seededSlug=product.slug;title=product.title;category=product.category;summary=product.summary;description=product.description;price=product.price;extendedPrice=product.extendedPrice??Number((product.price*2.5).toFixed(2));compatibility=product.compatibility;maxVersion=product.maxVersion;sourceFiles=product.sourceFiles;dependencies=product.dependencies;performance=product.performance;licence=product.licence;tagsText=product.tags.join(', ');featuresText=product.features.join('\n');contentsText=product.contents.join('\n');formatsText=product.formats.join(', ');showcaseVideoUrl=product.showcaseVideoUrl??'';versionNumber='';releaseNotes='';packageFile=undefined;documentationFile=undefined;
  }
  $: showcaseVideo=parseShowcaseVideoUrl(showcaseVideoUrl);
  $: showcaseVideoError=showcaseVideoUrl.trim()&&!showcaseVideo?'Enter a valid YouTube or Vimeo video URL.':'';
  $: healthItems=product?[Boolean(title.trim()),Boolean(summary.trim()),Boolean(description.trim()),Boolean(category),Boolean(product.images.length),Boolean(product.versions.length),Boolean(licence.trim()),Boolean(compatibility.trim()),!showcaseVideoError]:[];
  $: healthScore=healthItems.length?Math.round(healthItems.filter(Boolean).length/healthItems.length*100):0;
  $: commissionRate=Math.max(0,Math.min(100,Number($creatorProfile.commission||0)));
  $: estimatedCommission=price*(commissionRate/100);
  $: estimatedEarnings=price-estimatedCommission;

  const lines=(value:string)=>value.split(/\r?\n/).map(item=>item.trim()).filter(Boolean);
  const commaList=(value:string)=>value.split(',').map(item=>item.trim()).filter(Boolean);
  const selectedFile=(event:Event)=>(event.currentTarget as HTMLInputElement).files?.[0];

  async function save(){
    if(!product)return;
    if(extendedPrice<price){showToast('Extended licence price cannot be below the standard price','warning');return;}
    if(showcaseVideoError){showToast(showcaseVideoError,'warning');tab='Presentation';return;}
    await updateCreatorProduct(product.slug,{title,category,summary,description,price,extendedPrice,compatibility,maxVersion,sourceFiles,dependencies,performance,licence,tags:commaList(tagsText),features:lines(featuresText),contents:lines(contentsText),formats:commaList(formatsText),showcaseVideoUrl:showcaseVideo?.canonicalUrl??''});
  }
  async function submitReview(){if(product){await save();await setProductStatus(product.slug,'In review');}}
  async function deleteDraft(){if(!product||!confirm(`Delete the draft “${product.title}”? Uploaded files will also be removed.`))return;await removeCreatorProduct(product.slug);await goto('/creator/products');}
  async function uploadVersion(){
    if(!product||!packageFile||!versionNumber.trim()||releaseNotes.trim().length<10){showToast('Choose a package and enter a version number with release notes','warning');return;}
    versionBusy=true;
    try{
      const response=await apiRequest<{versionId:string;uploads:{bucket:string;path:string;token:string;role:string;type:string}[]}>(`/api/vendor/products/${product.slug}/versions`,{method:'POST',body:JSON.stringify({version:versionNumber,releaseNotes,package:{name:packageFile.name,size:packageFile.size,type:packageFile.type||'application/octet-stream'},documentation:documentationFile?{name:documentationFile.name,size:documentationFile.size,type:documentationFile.type||'application/octet-stream'}:undefined})});
      const client=getSupabaseBrowserClient();
      for(const upload of response.uploads){const file=upload.role==='package'?packageFile:documentationFile;if(!file)continue;const {error}=await client.storage.from(upload.bucket).uploadToSignedUrl(upload.path,upload.token,file,{contentType:file.type||upload.type});if(error)throw error;}
      await apiRequest(`/api/vendor/products/${product.slug}/versions`,{method:'PATCH',body:JSON.stringify({versionId:response.versionId})});
      await loadCreatorData(true);versionNumber='';releaseNotes='';packageFile=undefined;documentationFile=undefined;showToast('New version submitted for moderation','success');
    }catch(error){showToast(error instanceof Error?error.message:'Version upload failed','warning');}
    finally{versionBusy=false;}
  }
</script>

<svelte:head><title>{product?.title ?? 'Product unavailable'} — Creator Hub</title></svelte:head>
{#if product}
<header class="product-head"><a href="/creator/products">← All products</a><div class="head-main"><img src={product.image} alt=""/><div><div class="head-status"><StatusPill status={product.status}/><span>{product.category}</span><span>v{product.version}</span></div><h1>{product.title}</h1><p>Last updated {product.updated} · {product.views.toLocaleString('en-GB')} listing views</p></div><div class="actions">{#if product.status==='Published'}<a class="button button-secondary" href={`/marketplace/${product.slug}`}><Icon name="eye" size={17}/> View listing</a>{/if}<button class="button button-primary" type="button" onclick={save}><Icon name="check" size={17}/> Save changes</button></div></div></header>

{#if product.status==='Changes required'}<div class="notice warning"><Icon name="alert" size={20}/><div><b>Marketplace review requested changes</b><p>{product.moderationNote||'Review the listing and package, then resubmit when the requested changes are complete.'}</p></div><button type="button" onclick={submitReview}>Resubmit for review</button></div>{/if}
{#if product.status==='In review'}<div class="notice review"><Icon name="clock" size={20}/><div><b>This release is being reviewed</b><p>This listing is temporarily unavailable in the marketplace until an administrator approves the release.</p></div><span>Moderation pending</span></div>{/if}

<nav class="tabs glass">{#each ['Overview','Pricing & licence','Files & versions','Presentation','Support'] as item}<button class:active={tab===item} type="button" onclick={()=>tab=item}>{item}</button>{/each}</nav>
<div class="editor-grid">
  <main>
    {#if tab==='Overview'}
      <section class="panel glass"><div class="panel-title"><div><span class="eyebrow">Listing essentials</span><h2>Product information</h2></div><span class="score">Completion <b>{healthScore}%</b></span></div><label>Product title<input bind:value={title} maxlength="120"/></label><div class="two"><label>Category<select bind:value={category}>{#each $catalogueCategories as item}<option value={item.name}>{item.name}</option>{/each}</select></label><label>Performance profile<select bind:value={performance}><option>Lightweight</option><option>Mid-range</option><option>High detail</option></select></label></div><label>Short summary<textarea rows="3" bind:value={summary} maxlength="300"></textarea><small>{summary.length}/300 characters</small></label><label>Full description<textarea rows="10" bind:value={description}></textarea></label><div class="two"><label>Compatibility<input bind:value={compatibility}/></label><label>Minimum MAX version<select bind:value={maxVersion}><option>2024+</option><option>2025+</option><option>2026+</option><option>Any MAX build</option></select></label></div><div class="two"><label>Dependencies<input bind:value={dependencies}/></label><label class="check"><input type="checkbox" bind:checked={sourceFiles}/> Source files included</label></div><label>Search tags<input bind:value={tagsText} placeholder="environment, medieval, modular"/><small>Comma-separated</small></label><label>Key features<textarea rows="5" bind:value={featuresText} placeholder="One feature per line"></textarea></label><label>Package contents<textarea rows="5" bind:value={contentsText} placeholder="One item per line"></textarea></label><label>File formats<input bind:value={formatsText} placeholder="FBX, PNG, WAV"/><small>Comma-separated</small></label></section>
    {:else if tab==='Pricing & licence'}
      <section class="panel glass"><div class="panel-title"><div><span class="eyebrow">Commercial setup</span><h2>Price and licence tiers</h2></div></div><div class="price-grid"><label><span>Standard commercial licence</span><div class="money"><b>£</b><input type="number" min="0" step="0.01" bind:value={price}/></div></label><label><span>Extended team licence</span><div class="money"><b>£</b><input type="number" min="0" step="0.01" bind:value={extendedPrice}/></div></label></div><div class="fee-preview"><span><small>Buyer pays</small><b>£{price.toFixed(2)}</b></span><span><small>Estimated commission ({commissionRate.toFixed(2).replace(/\.00$/,'')}%)</small><b>−£{estimatedCommission.toFixed(2)}</b></span><span><small>Estimated earnings</small><strong>£{estimatedEarnings.toFixed(2)}</strong></span></div><label>Licence summary<textarea rows="7" bind:value={licence}></textarea></label><p class="help-copy">Final commission is calculated server-side from your vendor agreement, category override and the marketplace setting active at checkout.</p></section>
    {:else if tab==='Files & versions'}
      <section class="panel glass"><div class="panel-title"><div><span class="eyebrow">Controlled delivery</span><h2>Versions and packages</h2></div></div>{#if product.versions.length}<div class="version-list">{#each product.versions as item}<article class:current={item.isCurrent}><div>{#if item.isCurrent}<span>Current</span>{/if}<b>v{item.version}</b><small>{item.created} · {item.size}</small></div><em>{item.status.replaceAll('_',' ')}</em><small class="release">{item.releaseNotes||'No release notes supplied.'}</small></article>{/each}</div>{:else}<div class="empty-panel"><Icon name="package" size={28}/><b>No package version found</b><small>Complete the original upload before submitting this product.</small></div>{/if}
      {#if product.status!=='In review'}<div class="version-form"><h3>Submit a new version</h3><div class="two"><label>Version number<input bind:value={versionNumber} placeholder="1.1.0"/></label><label>Asset package<input type="file" onchange={(event)=>packageFile=selectedFile(event)}/></label></div><label>Release notes<textarea rows="5" bind:value={releaseNotes} placeholder="Describe compatibility changes, fixes and new content."></textarea></label><label>Documentation file <small>Optional</small><input type="file" onchange={(event)=>documentationFile=selectedFile(event)}/></label><button class="button button-primary" type="button" disabled={versionBusy} onclick={uploadVersion}><Icon name="upload" size={17}/>{versionBusy?'Uploading…':'Upload and submit version'}</button></div>{/if}</section>
    {:else if tab==='Presentation'}
      <section class="panel glass"><div class="panel-title"><div><span class="eyebrow">Buyer confidence</span><h2>Preview gallery</h2></div><span class="score">{product.images.length}/12 images</span></div>{#if product.images.length}<div class="media-grid">{#each product.images as image,index}<div class:cover={index===0}><img src={image} alt={`${product.title} preview ${index+1}`}/><span>{index===0?'Cover image':`Preview ${index+1}`}</span></div>{/each}</div>{:else}<div class="empty-panel"><Icon name="image" size={28}/><b>No preview media uploaded</b><small>A product cannot be approved until its original signed uploads are complete.</small></div>{/if}<div class="video-field"><label>Showcase video <small>Optional · YouTube or Vimeo</small><input type="url" bind:value={showcaseVideoUrl} placeholder="https://www.youtube.com/watch?v=…"/></label>{#if showcaseVideo}<iframe src={showcaseVideo.embedUrl} title={`${product.title} showcase video`} loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe>{:else if showcaseVideoError}<div class="video-error"><Icon name="alert" size={16}/>{showcaseVideoError}</div>{/if}</div><p class="help-copy">Preview media from the approved submission is public. Asset packages remain private and are delivered only through entitlement-checked signed URLs.</p></section>
    {:else}
      <section class="panel glass"><div class="panel-title"><div><span class="eyebrow">After-sale experience</span><h2>Support and buyer guidance</h2></div></div><div class="support-summary"><span><small>Store response target</small><b>{$storefront.responseTime||'Not configured'}</b></span><span><small>Support email</small><b>{$storefront.supportEmail||'Not configured'}</b></span></div><label>Store support promise<textarea rows="5" readonly value={$storefront.supportPromise||'No support promise has been published.'}></textarea></label><label>Update commitment<textarea rows="5" readonly value={$storefront.updateCommitment||'No update commitment has been published.'}></textarea></label><a class="button button-secondary" href="/creator/storefront"><Icon name="settings" size={17}/> Edit storefront policies</a></section>
    {/if}
  </main>
  <aside>
    <section class="health glass"><span class="eyebrow">Listing health</span><div class="ring" style={`--score:${healthScore*3.6}deg`}><b>{healthScore}</b><small>/100</small></div><h3>{healthScore===100?'Ready for review':'Complete the listing'}</h3><p>This score reflects required listing, package and preview data already stored for this product.</p><ul><li class:done={Boolean(summary&&description)}><Icon name={summary&&description?'check':'plus'} size={14}/> Description complete</li><li class:done={product.versions.length>0}><Icon name={product.versions.length?'check':'plus'} size={14}/> Package uploaded</li><li class:done={product.images.length>0}><Icon name={product.images.length?'check':'plus'} size={14}/> Preview media uploaded</li><li class:done={Boolean(licence)}><Icon name={licence?'check':'plus'} size={14}/> Licence configured</li></ul></section>
    <section class="stats glass"><h3>Product performance</h3><div><span><small>Revenue</small><b>£{product.revenue.toLocaleString('en-GB',{minimumFractionDigits:2})}</b></span><span><small>Sales</small><b>{product.sales.toLocaleString('en-GB')}</b></span><span><small>Conversion</small><b>{product.conversion?`${product.conversion}%`:'—'}</b></span><span><small>Rating</small><b>{product.rating?`${product.rating} ★`:'—'}</b></span></div><a href="/creator/analytics">Open analytics →</a></section>
    <section class="danger glass"><h3>Product actions</h3>{#if product.status==='Published'}<button type="button" onclick={()=>setProductStatus(product.slug,'Retired')}><Icon name="minus" size={16}/> Retire from sale</button>{:else if product.status!=='In review'}<button type="button" onclick={submitReview}><Icon name="check" size={16}/> Submit for review</button>{/if}{#if product.status==='Draft'||product.status==='Changes required'}<button class="destructive" type="button" onclick={deleteDraft}><Icon name="trash" size={16}/> Delete draft and files</button>{/if}</section>
  </aside>
</div>
{:else}
<section class="empty-page glass"><span class="eyebrow">Creator products</span><h1>Product unavailable.</h1><p>This product does not exist or does not belong to your creator account.</p><a class="button button-primary" href="/creator/products">Return to products</a></section>
{/if}

<style>
