-size:8px}.score b{color:#24d89a}.panel label{display:grid;gap:7px;color:#aab5c8;font-size:9px;font-weight:750}.panel input,.panel select,.panel textarea{width:100%;padding:0 11px;border:1px solid #183352;border-radius:8px;outline:0;color:#f5f8ff;background:#050a16}.panel input,.panel select{min-height:43px}.panel input[type='file']{padding:10px}.panel textarea{padding-block:10px;resize:vertical;line-height:1.5}.panel input:focus,.panel select:focus,.panel textarea:focus{border-color:#00e5ff}.panel label>small{color:#718096;font-size:7px;font-weight:500}.two{margin:13px 0;display:grid;grid-template-columns:1fr 1fr;gap:12px}.check{align-content:center;grid-template-columns:auto 1fr!important}.check input{width:auto;min-height:auto;accent-color:#00e5ff}.price-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.price-grid>label{padding:16px;border:1px solid #183352;border-radius:11px;background:#071225}.money{display:flex;align-items:center;border:1px solid #27547a;border-radius:9px;background:#030711}.money b{padding-left:12px;color:#00e5ff}.money input{border:0;background:transparent;font-size:23px;font-weight:850}.fee-preview{margin:15px 0;padding:15px;display:grid;grid-template-columns:repeat(3,1fr);border:1px solid #183352;border-radius:11px;background:#050a16}.fee-preview span{display:grid}.fee-preview span+span{padding-left:15px;border-left:1px solid #183352}.fee-preview small{color:#718096;font-size:7px}.fee-preview b,.fee-preview strong{margin-top:4px;font-size:15px}.fee-preview strong{color:#24d89a}.help-copy{color:#718096;font-size:8px;line-height:1.6}.version-list{margin-bottom:18px;border:1px solid #183352;border-radius:11px;overflow:hidden}.version-list article{min-height:72px;padding:10px 13px;display:grid;grid-template-columns:150px 100px 1fr;gap:12px;align-items:center;border-top:1px solid #183352}.version-list article:first-child{border-top:0}.version-list article.current{background:rgb(0 229 255/.05)}.version-list div{display:grid}.version-list