f;border-right-color:#8b5cf6;border-radius:50%;box-shadow:0 0 30px rgb(0 229 255/.12)}.ring b{font-size:27px}.ring small{color:#718096;font-size:8px}.health h3{text-align:center}.health>p{text-align:center;color:#718096;font-size:8px;line-height:1.5}.health ul{padding:0;list-style:none}.health li{padding:8px 0;display:flex;align-items:center;gap:7px;border-top:1px solid #122a43;color:#718096;font-size:8px}.health li.done{color:#24d89a}.stats h3,.danger h3{margin-top:0}.stats>div{display:grid;grid-template-columns:1fr 1fr}.stats span{padding:11px 0;display:grid;border-top:1px solid #122a43}.stats span:nth-child(even){padding-left:12px;border-left:1px solid #122a43}.stats small{color:#718096;font-size:7px}.stats b{margin-top:3px;font-size:11px}.stats>a{margin-top:12px;display:block;color:#00e5ff;font-size:8px;font-weight:800}.danger button{width:100%;min-height:38px;margin-top:7px;padding:0 10px;display:flex;align-items:center;gap:8px;border:1px solid #183352;border-radius:8px;color:#aab5c8;background:#071225;cursor:pointer;font-size:8px}.danger button:hover{color:#ffb547;border-color:#ffb547}.danger button.destructive{color:#ff6b7a}.empty-page{max-width:720px;margin:70px auto;text-align:center}.empty-page .button{display:inline-flex;width:auto}
  @media(max-width:980px){.editor-grid{grid-template-columns:1fr}.editor-grid aside{grid-template-columns:repeat(3,1fr)}.head-main{grid-template-columns:80px 1fr}.actions{grid-column:1/-1}.actions .button{flex:1}}
  @media(max-width:680px){.head-main{grid-template-columns:1fr}.head-main>img{width:100%;height:150px}.two,.price-grid,.fee-preview,.media-grid,.support-summary{grid-template-columns:1fr}.editor-grid aside{grid-template-columns:1fr}.actions{display:grid}.notice{grid-template-columns:auto 1fr}.notice button,.notice>span{grid-column:1/-1}.version-list article{grid-template-columns:1fr}.version-list .release{grid-column:1}.panel .button{width:100%}}
</style>
